insert into public.hadith_families(slug,title,family_type,scope,narrative_group_id,verification_status,created_by,method) values ('lying-about-the-prophet','"Whoever Lies About Me Deliberately" (man kadhaba ʿalayya)','statement','Reports of the warning "whoever lies about me (deliberately), let him take his seat in the Fire", including the variant "whoever says about me what I did not say". Classically counted as mutawātir; here 13 companions in the six books and Musnad Aḥmad. Other hadith that merely share the ending "let him take his seat in the Fire" (standing for a man, false lineage, false oath, seeking knowledge for other than Allah, speaking about the Qurʾān without knowledge, lying about a dream) are different statements and excluded.',null,'source_checked','grok-bot','hce-rules-v1') on conflict (slug) do nothing;
