insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='lying-about-the-prophet'),'conclusion',1,'Twenty-nine indexed records from thirteen companions carry the warning: al-Zubayr 5, Abū Hurayra 4, ʿAlī 3, Anas 3, Ibn Masʿūd 3, ʿAbd Allāh b. ʿAmr 2, al-Mughīra 2, Abū Saʿīd 2, and one each from ʿUthmān, Salama b. al-Akwaʿ, Jābir, Abū Qatāda and Ibn ʿAbbās. That is the broadest companion spread of any family so far, with no common link across companions, which fits its classical description as mutawātir (candidate).',array['bukhari:107','bukhari:108','bukhari:109','bukhari:110','muslim:4a','bukhari:3461','ibnmajah:30','ahmad:469']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='lying-about-the-prophet'),'conclusion',2,'Two formulations circulate. "Whoever lies about me (deliberately)" is used by most companions. "Whoever says about me what I did not say" is used by ʿUthmān, Salama, and Abū Hurayra via Abū Salama and Abū Qatāda. Both state the same warning: a wording variant, not a different claim.',array['ahmad:469','bukhari:109','ibnmajah:34','ibnmajah:35','muslim:3']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='lying-about-the-prophet'),'conclusion',3,'"Deliberately" (mutaʿammidan) is absent in some routes of al-Zubayr (Bukhārī 107, Aḥmad 1428), and narrators express doubt over it in Ibn Mājah 32 (Anas) and Muslim 3004 (Hammām). Its absence is omission, not contradiction.',array['bukhari:107','ahmad:1428','ibnmajah:32','muslim:3004','abudawud:3651']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='lying-about-the-prophet'),'conclusion',4,'Several companions give the warning as their reason for narrating little: al-Zubayr when his son asks, Anas ("it prevents me from narrating much to you") and ʿUthmān. This is complementary context.',array['bukhari:107','bukhari:108','ahmad:469']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='lying-about-the-prophet'),'conclusion',5,'Some reports embed the warning in a longer statement: "lying about me is not like lying about anyone" (al-Mughīra), "convey from me even one verse" (ʿAbd Allāh b. ʿAmr), "do not write from me other than the Qurʾān" (Abū Saʿīd, Muslim 3004), speaking on the Qurʾān by opinion (Ibn ʿAbbās), the name/kunya and dream clauses (Abū Hurayra), and al-Ḥudaybiya (ʿAlī, Tirmidhī 3715). All are complementary.',array['bukhari:1291','bukhari:3461','muslim:3004','tirmidhi:2951','bukhari:110','tirmidhi:3715']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='lying-about-the-prophet'),'uncertainty',1,'Many short-form names (Khālid, Sharīk, Manṣūr, ʿAṭiyya, Muṭarrif, Ḥabīb, Thaʿlaba) are proposed identifications that were not source-checked.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='lying-about-the-prophet'),'uncertainty',2,'Aḥmad 1075 is a zawāʾid report of ʿAbd Allāh b. Aḥmad; the opening "ʿAbd Allāh" is identified on that basis (proposal).','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='lying-about-the-prophet'),'uncertainty',3,'The Aḥmad numbers stored in the corpus (439, 550, 1021, 1337, 1351) differ from sunnah.com (469, 584, 1075, 1413, 1428).','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='lying-about-the-prophet'),'uncertainty',4,'Musnad Aḥmad holds many more companion routes than the corpus contains, so this family is not exhaustive.','grok-bot') on conflict do nothing;
